function telHref(phone) { return phone ? `tel:${phone.replace(/[^\d+]/g, "")}` : null; }
function mailHref(email) { return email ? `mailto:${email}` : null; }
function waHref(number) { return number ? `https://wa.me/${number}` : null; }

