// Real logos go here as their own base64 constants (this project embeds all
// imagery directly rather than using separate asset files — see the
// IMAGE_LIBRARY / LOGO_IMAGE pattern above). To add a real logo: encode it
// the same way and add a PARTNER_LOGO_* constant, then reference it below.
const PARTNER_LOGO_POSITIVE_IMPACT_TOURISM = "data:image/jpeg;base64,";

// Neutral placeholder for partners whose real logo hasn't been supplied yet
// — a plain labelled box, never a guessed or invented logo.
function placeholderPartnerLogo(label) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200"><rect width="100%" height="100%" fill="#F7F3EA"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" font-family="Inter, sans-serif" font-size="18" fill="#6b7268">${label}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

